import 'package:gql/language.dart';
import 'package:gql/ast.dart';
import 'package:normalize/normalize.dart';

final DocumentNode query = parseString('''
  query TestQuery {
    posts { id __typename author { id __typename name } title }
  }
''');

final data = {"posts":[{"id":"123","__typename":"Post","author":{"id":"1","__typename":"Author","name":"Paul"},"title":"My post"}]};

final normalized = {};
normalizeOperation(
  merge:(dataId,value)=> (normalized[dataId]??={}).addAll(value),
  document:query,
  data:data,
);
print(normalized);
